document.querySelector("#orders tbody").addEventListener("click", async (e) => {
  const btn = e.target.closest("[data-juntar-id]");
  if (!btn) return;
  const order = allOrders.find(o => String(o.id) === btn.dataset.juntarId);
  if (!order) return;
  if (order.grupoEnvio) {
    const otros = pedidosDelGrupo(order).filter(o => o.id !== order.id).map(refLabel).join(", ");
    if (!confirm("¿Separar " + refLabel(order) + " del envío conjunto con " + otros + "?\\n\\nVolverá a salir por su cuenta (un colchón volverá a SEUR).")) return;
    const res = await fetch("/api/pedidos/shopify/grupo-envio/desvincular", {
      method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ orderId: order.id }),
    });
    const r = await res.json().catch(() => ({}));
    if (!res.ok) alert("No se ha podido separar: " + (r.error || res.status));
  } else {
    const texto = prompt("¿Con qué pedido se envía junto " + refLabel(order) + "?\\nEscribe el número (ej. BEZEN12233 o 12233):");
    if (!texto) return;
    const limpio = texto.trim().toUpperCase();
    const numero = Number(limpio.replace(/^BEZEN/, ""));
    const otro = allOrders.find(o => o.id !== order.id && ((numero && o.platform === "Shopify" && o.orderNumber === numero) || (o.orderRef || "").toUpperCase() === limpio));
    if (!otro) { alert("No encuentro el pedido " + texto + "."); return; }
    const nombreLimpio = s => (s || "").normalize("NFD").replace(/[\\u0300-\\u036f]/g, "").trim().toLowerCase();
    if (nombreLimpio(otro.name) !== nombreLimpio(order.name)
      && !confirm("Ojo: los nombres no coinciden (" + order.name + " / " + otro.name + "). ¿Juntarlos igualmente?")) return;
    const res = await fetch("/api/pedidos/shopify/grupo-envio/vincular", {
      method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ orderIds: [order.id, otro.id] }),
    });
    const r = await res.json().catch(() => ({}));
    if (!res.ok) { alert("No se han podido juntar: " + (r.error || res.status)); return; }
    alert(refLabel(order) + " y " + refLabel(otro) + " saldrán juntos por Furniture, en un solo envío.");
  }
  await loadOrders();
  loadPendientes();
});
document.querySelector("#orders tbody").addEventListener("click", async (e) => {
  const btn = e.target.closest("[data-pago-manual-id]");
  if (!btn) return;
  const order = allOrders.find(o => String(o.id) === btn.dataset.pagoManualId);
  if (!order) return;
  if (!confirm("¿Confirmas que el cliente ya ha pagado " + refLabel(order) + "?\\n\\nSe tramitará ahora con fecha de hoy y aparecerá en Proveedores para pedirlo a fábrica. Cuando se marque como pagado en Shopify no se volverá a tramitar.")) return;
  btn.disabled = true;
  btn.textContent = "Tramitando…";
  const res = await fetch("/api/pedidos/shopify/admin/tramitar-pagado-manual", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ orderId: order.id, usuario: currentUser }),
  });
  const r = await res.json().catch(() => ({}));
  if (res.ok && r.decisionSeur) {
    alert("Pago apuntado ✔\\n\\n" + refLabel(order) + " lleva varios colchones por SEUR y solo hay stock de una parte:\\n" + ((r.seurMixedInfo && r.seurMixedInfo.colchones) || []).map(c => "· " + nombreCortoModelo(c.stockModel) + " " + c.talla + ": " + c.disponible + " de " + c.cantidad + " en stock").join("\\n") + "\\n\\nDecide en SEUR › «pendientes de decidir»: dividir ahora (sale ya lo que hay) o esperar a tenerlo todo (se tramita solo cuando llegue).");
  } else if (!res.ok || !r.inventoryProcessed) {
    alert("No se ha podido tramitar: " + (r.error || "revisa el pedido (quizá el procesamiento está en pausa)."));
  }
  await loadOrders();
  loadPendientes();
});
document.querySelector("#orders tbody").addEventListener("click", async (e) => {
  const btn = e.target.closest("[data-cancel-id]");
  if (!btn) return;
  const order = allOrders.find(o => String(o.id) === btn.dataset.cancelId);
  if (!order) return;
  const nuevoEstado = !order.cancelado;
  if (nuevoEstado && !confirm("¿Cancelar el pedido " + refLabel(order) + "?")) return;
  order.cancelado = nuevoEstado;
  await saveMeta(order.id, { cancelado: nuevoEstado });
  render(currentFiltered());
});

async function saveMeta(id, patch) {
  try {
    await fetch("/api/pedidos/shopify/meta", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ id, ...patch }),
    });
  } catch (e) {
    console.error("No se pudo guardar", e);
  }
  if (patch.notas !== undefined && notaTodoJunto(patch.notas)) await aplicarTodoJunto(id);
}

// "LO QUIERE TODO JUNTO" en las notas (Jennifer, 2026-10-05): el colchón
// pasa solo de FPK a FUR y en Furniture se avisa de no sacarlo por separado.
function notaTodoJunto(texto) {
  return /TODO\\s+JUNTO/.test(String(texto || "").normalize("NFD").replace(/[\\u0300-\\u036f]/g, "").toUpperCase());
}
function pedidoQuiereTodoJunto(order) {
  return !!order && pedidosDelGrupo(order).some(p => notaTodoJunto(p.notas));
}
// Solo colchones que pueden ir con Furniture (de pack, con tapicería en el
// pedido o pedido ya de Furniture) — un colchón que va solo por SEUR también
// lleva FPK por defecto y ese no se toca.
async function aplicarTodoJunto(orderId) {
  const order = allOrders.find(o => String(o.id) === String(orderId));
  if (!order) return;
  if (!backorders.length) backorders = await (await fetch("/api/inventario/pendientes")).json();
  const grupo = pedidosDelGrupo(order);
  const vaConFurniture = grupo.some(p => p.agencia === "FURNITURE") || ordenTieneTapiceria(order.orderNumber);
  const colchones = backorders.filter(b => grupo.some(p => p.id === b.orderId)
    && b.tipo === "colchon" && b.tipoEnvio === "FPK"
    && (b.estado === "pendiente" || b.estado === "cubierto")
    && !b.reposicion && !b.gestoComercial
    && (b.esPack || vaConFurniture));
  if (!colchones.length) return;
  for (const b of colchones) {
    await fetch("/api/inventario/pendientes/" + encodeURIComponent(b.id) + "/plan", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ tipoEnvio: "FUR" }),
    });
    b.tipoEnvio = "FUR";
  }
  mostrarAvisoBreve("Todo junto: " + colchones.map(b => b.stockModel + (b.talla ? " (" + b.talla + ")" : "")).join(", ") + " de " + refLabel(order) + " pasa de FPK a FUR.");
  loadPendientes();
}

async function loadOrders() {
  const res = await fetch("/api/pedidos/shopify");
  allOrders = await res.json();
  applyFilter();
  revisarAvisosMontana();
  revisarAvisosDocumentacionSeur();
  revisarAvisosTiktok();
}

// Pedidos de TikTok (Jennifer, 2026-10-28): NUNCA se tramitan, pero sus
// datos sirven para llamar al cliente y que lo compre en nuestra web. Aviso
// con los datos de contacto hasta que se apunte el seguimiento. "Más tarde"
// lo aparta hasta recargar la página.
let tiktokAvisoAplazado = false;
const TIKTOK_ESTADOS = { contactado: "📞 Contactado", "compra-web": "🛒 Lo compra en la web", "no-interesa": "✖ No le interesa" };
function tiktokPendientes() {
  return allOrders.filter(o => o.tiktokRetenido && !o.tiktokRevision && !o.inventoryProcessed && !o.cancelado && !o.shopifyCancelado);
}
function revisarAvisosTiktok() {
  const ov = document.getElementById("tiktok-modal-overlay");
  const lista = tiktokPendientes();
  if (!lista.length) { ov.classList.remove("open"); return; }
  if (tiktokAvisoAplazado) return;
  const cont = document.getElementById("tiktok-modal-lista");
  cont.innerHTML = lista.map((o, i) => '<div style="border:1px solid #ddd;border-radius:8px;padding:10px;margin:8px 0">'
    + "<b>" + escapeAttr(refLabel(o)) + "</b> · " + escapeAttr(new Date(o.orderDate).toLocaleDateString("es-ES"))
    + "<br><b>" + escapeAttr(o.name || "") + "</b> · 📞 <b>" + escapeAttr(o.phone || "sin teléfono") + "</b>"
    + "<br>" + escapeAttr(o.address || "")
    + "<br>" + escapeAttr(o.product || "") + " · <b>" + escapeAttr(o.price || "") + " €</b>"
    + '<div style="margin-top:8px;display:flex;gap:6px;flex-wrap:wrap">'
    + Object.entries(TIKTOK_ESTADOS).map(([k, t]) => '<button type="button" class="secondary tiktok-estado" data-i="' + i + '" data-estado="' + k + '">' + t + "</button>").join("")
    + "</div></div>").join("");
  cont.querySelectorAll(".tiktok-estado").forEach(b => b.addEventListener("click", async () => {
    const o = lista[Number(b.dataset.i)];
    const nota = prompt(TIKTOK_ESTADOS[b.dataset.estado] + " · " + refLabel(o) + "\\nNota (opcional):", "");
    if (nota === null) return;
    b.disabled = true;
    await seguimientoTiktok(o, b.dataset.estado, nota);
  }));
  document.getElementById("tiktok-modal-luego").onclick = () => { tiktokAvisoAplazado = true; ov.classList.remove("open"); };
  ov.classList.add("open");
}
async function seguimientoTiktok(o, estado, nota) {
  const res = await fetch("/api/pedidos/tiktok-decision", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ orderId: o.id, estado, nota, usuario: currentUser || "" }) });
  const d = await res.json().catch(() => ({}));
  if (!res.ok || !d.ok) { alert(d.error || "No se ha podido guardar (" + res.status + ")."); return; }
  await loadOrders();
}
function tiktokTag(o) {
  if (o.paymentMethod !== "TIKTOK_SHOP" || !o.tiktokRetenido) return "";
  const r = o.tiktokRevision;
  const base = '<br><span class="badge" style="background:#fee2e2;color:#991b1b">🎵 TikTok · NO SE TRAMITA</span>';
  if (!r) return base + '<br><button type="button" class="badge tiktok-revisar-btn" style="background:#fef3c7;color:#92400e;border:0;cursor:pointer">📞 Pendiente de contactar</button>';
  return base + '<br><button type="button" class="badge tiktok-cambiar-btn" data-tiktok-id="' + escapeAttr(o.id) + '" style="background:#e0f2fe;color:#075985;border:0;cursor:pointer" title="'
    + escapeAttr((r.usuario || "") + " · " + new Date(r.fecha).toLocaleString("es-ES") + (r.nota ? " · " + r.nota : "") + " (pulsa para cambiar)") + '">' + escapeAttr(TIKTOK_ESTADOS[r.estado] || r.estado) + "</button>"
    + (r.nota ? '<br><small style="color:var(--muted)">' + escapeAttr(r.nota) + "</small>" : "");
}
document.addEventListener("click", async (e) => {
  if (e.target.closest(".tiktok-revisar-btn")) { tiktokAvisoAplazado = false; revisarAvisosTiktok(); return; }
  const cam = e.target.closest(".tiktok-cambiar-btn");
  if (!cam) return;
  const o = allOrders.find(x => String(x.id) === cam.dataset.tiktokId);
  if (!o) return;
  const opciones = Object.keys(TIKTOK_ESTADOS);
  const n = prompt("Seguimiento de " + refLabel(o) + ":\\n" + opciones.map((k, i) => (i + 1) + ". " + TIKTOK_ESTADOS[k]).join("\\n") + "\\n\\nEscribe el número:", "");
  const estado = opciones[Number(n) - 1];
  if (!estado) return;
  const nota = prompt("Nota (opcional):", (o.tiktokRevision && o.tiktokRevision.nota) || "");
  if (nota === null) return;
  await seguimientoTiktok(o, estado, nota);
});

let filtroCampanas = false;
function currentFiltered() {
  const q = document.getElementById("search").value.trim().toLowerCase();
  const colorFilter = hasColorAccess() ? document.getElementById("color-filter").value : "";
  const estadoFilter = document.getElementById("estado-filter").value;
  const paymentFilter = document.getElementById("payment-filter").value;
  // allOrders trae todas las plataformas (Furniture/SEUR/Proveedores lo
  // necesitan así) — la tabla de Pedidos > Shopify se queda solo con los
  // suyos (Jennifer, 2026-09-17: pantallas separadas por plataforma;
  // generalizado 2026-09-19 al añadir Maison Du Monde).
  let filtered = allOrders.filter(o => o.platform === "Shopify" || !o.platform);
  // Campanas pendientes de resolver (Jennifer, 2026-11-05): needsReview sin
  // todas las preguntas contestadas (la campana roja, no la ya contestada).
  const campanaPendiente = o => o.needsReview && !isReviewAnswered(o) && !o.cancelado && o.shippingStatus !== "fulfilled";
  const nCampanas = filtered.filter(campanaPendiente).length;
  const cntEl = document.getElementById("campanas-filter-count");
  if (cntEl) cntEl.textContent = "(" + nCampanas + ")";
  const btnCamp = document.getElementById("campanas-filter-btn");
  if (btnCamp) btnCamp.classList.toggle("secondary", !filtroCampanas);
  if (filtroCampanas) filtered = filtered.filter(campanaPendiente);
  if (q) {
    filtered = filtered.filter(o => ("bezen" + o.orderNumber).includes(q) || (o.name || "").toLowerCase().includes(q));
  }
  if (colorFilter) {
    filtered = filtered.filter(o => o.colorTag === colorFilter);
  }
  // "Solo pendientes" (Jennifer, 2026-09-16): oculta los pedidos ya
  // terminados (enviados Y pagados) para que la lista no crezca sin límite
  // — se queda solo con los que aún necesitan atención por envío o pago.
  if (estadoFilter === "pendientes") {
    filtered = filtered.filter(o => o.shippingStatus !== "fulfilled" || o.paymentStatus !== "PAGADO");
  }
  if (paymentFilter === "PAGADO") {
    filtered = filtered.filter(o => o.paymentStatus === "PAGADO");
  } else if (paymentFilter === "PENDIENTE") {
    filtered = filtered.filter(o => o.paymentStatus === "PENDIENTE DE PAGO");
  } else if (paymentFilter === "REEMBOLSADO") {
    filtered = filtered.filter(o => o.paymentStatus === "REEMBOLSADO");
  }
  return filtered;
}

function applyFilter() {
  render(currentFiltered());
  actualizarBadgeAbiertos();
  actualizarBadgesPlazo();
}

