// "Ocultar ya recibidos de fábrica" marcado por defecto y recordado en este
// navegador (Jennifer, 2026-10-08): al marcar un colchón como recibido (y
// mandarse la reserva al almacén) la fila seguía a la vista, y al volver a
// pulsar se desmarcaba sin querer.
// Cada proveedor tiene las suyas (Jennifer, 2026-10-22: "prefiero que cada
// proveedor sea independiente"): se guardan por pestaña. Sin nada guardado
// para esa pestaña, se usa lo que había antes en común.
function casillaProveedorGuardada(clave, prov, porDefecto) {
  try {
    const v = localStorage.getItem(clave + "_" + prov);
    const comun = localStorage.getItem(clave);
    return v != null ? v === "1" : comun != null ? comun === "1" : porDefecto;
  } catch (e) { return porDefecto; }
}
function aplicarCasillasProveedor(prov) {
  document.getElementById("pendientes-ocultar-recibidos").checked = casillaProveedorGuardada("hd_ocultar_recibidos", prov, true);
  document.getElementById("pendientes-mostrar-cancelados").checked = casillaProveedorGuardada("hd_mostrar_cancelados", prov, false);
}
(() => {
  for (const [fid, clave] of [["pendientes-ocultar-recibidos", "hd_ocultar_recibidos"], ["pendientes-mostrar-cancelados", "hd_mostrar_cancelados"]]) {
    const chk = document.getElementById(fid);
    chk.addEventListener("change", () => {
      try { localStorage.setItem(clave + "_" + currentProveedorFilter, chk.checked ? "1" : "0"); } catch (e) { /* sin localStorage */ }
      renderPendientes();
    });
  }
  aplicarCasillasProveedor("polival");
})();
// Si la ventana cambia de tamaño el texto de la cabecera puede pasar a 1 o 2
// líneas y cambiar de alto — se re-mide (Jennifer, 2026-09-25, ver
// sincronizarTopFilaFiltro).
window.addEventListener("resize", () => {
  sincronizarTopFilaFiltro("pendientes-table", "pendientes-filter-row");
  sincronizarTopFilaFiltro("furniture-pendientes-table", "furniture-filter-row");
});
// Excel de todos los pendientes de proveedor (Jennifer, 2026-09-25): "por si
// tengo que hacer algo con ellos con el excel" — descarga TODOS los
// pendientes de Polival/Luso/New de golpe, sin importar la pestaña o los
// filtros de texto que haya puestos en pantalla ahora mismo (a diferencia de
// la tabla, que sí filtra). Mismas columnas que ya se ven en pantalla, más
// "Proveedor" para poder distinguirlos una vez mezclados en una sola hoja.
document.getElementById("descargar-excel-pendientes-btn").addEventListener("click", async () => {
  // Solo lo que FALTA POR VENIR de fábrica (Jennifer, 2026-10-16,
  // BEZEN12154/12155: "que el pedido siga pendiente de envío no quiere decir
  // que siga pendiente de venir"): lo ya recibido nunca sale aquí.
  const lista = backorders
    .filter(b => b.estado === "pendiente" && ["POLIVAL", "LUSO", "NEW"].includes(b.proveedor) && !b.recibidoFabrica)
    .sort((a, b) => (a.proveedor === b.proveedor ? parseFechaGenerica(a.fecha) - parseFechaGenerica(b.fecha) : a.proveedor.localeCompare(b.proveedor)));
  // Coste de tarifa de los colchones de Luso/New (Jennifer, 2026-09-30:
  // "cuando descargue la tabla de proveedores esos precios se puedan
  // descargar en la columna también") — como número, para poder sumar.
  await cargarCostesTarifa(lista.filter(b => b.proveedor === "LUSO" || b.proveedor === "NEW"));
  const costeUd = b => {
    if (b.proveedor !== "LUSO" && b.proveedor !== "NEW") return "";
    const c = costesTarifa.get(b.stockModel + "|" + tallaTarifa(b));
    return c && c.coste != null ? Math.round(c.coste * 100) / 100 : "";
  };
  const filas = lista
    .map(b => ({
      Proveedor: b.proveedor,
      Pedido: refLabel(b) + (b.refSuffix || ""),
      Plataforma: b.platform || "Shopify",
      Modelo: b.stockModel,
      Color: b.color || "",
      Talla: b.talla,
      SKU: skuDePendiente(b),
      Cantidad: b.cantidad,
      "Coste ud (tarifa)": costeUd(b),
      "Coste total (tarifa)": costeUd(b) === "" ? "" : Math.round(costeUd(b) * (b.cantidad || 1) * 100) / 100,
      "Ref. Polival": b.referencia || "",
      // Solo tiene sentido para lo que hay que pedir (Jennifer, 2026-10-06): un
      // colchón que sale de stock no lleva FUR ni FPK.
      "FUR/FPK": b.esPack && b.tipo === "colchon" && b.estado !== "cubierto" ? (b.tipoEnvio || "") : "",
      "Mercancía para pedir a fábrica": b.mercanciaFabrica || "",
      "Fecha del pedido": b.fecha || "",
      "Previsión de entrega": (b.fechaEstimadaLlegada || b.previsionEntrega) ? new Date((b.fechaEstimadaLlegada || b.previsionEntrega).slice(0, 10) + "T12:00:00").toLocaleDateString("es-ES") : "",
      "En revisión":b.revision ? (b.revision.motivo || "Sí") : "",
      "Cuarentena": b.cuarentena ? (b.cuarentena.motivo || "Sí") : "",
      Notas: (allOrders.find(o => String(o.id) === String(b.orderId)) || {}).notas || "",
      "Pedido a fábrica": b.pedidoGenerado ? "Sí" + (b.fechaPedidoFabrica ? " (" + new Date(b.fechaPedidoFabrica).toLocaleDateString("es-ES") + ")" : "") : "No",
      "Recibido de fábrica": b.recibidoFabrica ? "Sí" + (b.fechaRecibido ? " (" + new Date(b.fechaRecibido).toLocaleDateString("es-ES") + ")" : "") : "No",
    }));
  const ws = XLSX.utils.json_to_sheet(filas);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Pendientes proveedor");
  const fecha = new Date().toISOString().slice(0, 10);
  XLSX.writeFile(wb, "Pendientes_Proveedores_" + fecha + ".xlsx");
});
// Listado de lo mandado a apartar al almacén un día concreto (Jennifer,
// 2026-10-09: "cuando venga el camión, para que sea más sencillo") — todo
// pendiente con reservaEnviada ese día (hora de Madrid), agrupado por
// modelo y medida para cotejarlo con lo descargado.
(() => {
  const inp = document.getElementById("reservas-almacen-fecha");
  inp.value = new Date().toLocaleDateString("en-CA", { timeZone: "Europe/Madrid" });
})();
document.getElementById("descargar-reservas-almacen-btn").addEventListener("click", () => {
  const dia = document.getElementById("reservas-almacen-fecha").value;
  if (!dia) { alert("Elige el día."); return; }
  const diaMadrid = iso => new Date(iso).toLocaleDateString("en-CA", { timeZone: "Europe/Madrid" });
  const lista = backorders
    .filter(b => b.reservaEnviada && diaMadrid(b.reservaEnviada) === dia && b.estado !== "cancelado")
    .sort((a, b) => (a.stockModel + "|" + a.talla).localeCompare(b.stockModel + "|" + b.talla) || a.reservaEnviada.localeCompare(b.reservaEnviada));
  const diaEs = new Date(dia + "T12:00:00").toLocaleDateString("es-ES");
  if (!lista.length) { alert("No hay reservas al almacén del " + diaEs + "."); return; }
  const filas = lista.map(b => {
    const o = allOrders.find(x => String(x.id) === String(b.orderId)) || {};
    return {
      "Hora reserva": new Date(b.reservaEnviada).toLocaleTimeString("es-ES", { timeZone: "Europe/Madrid", hour: "2-digit", minute: "2-digit" }),
      Pedido: (b.tipo === "colchon" && b.tipoEnvio === "FUR" ? "FUR" : "") + refLabel(b) + (b.refSuffix || ""),
      Cliente: o.name || "",
      Tipo: b.tipo || "",
      Modelo: b.stockModel,
      Medida: b.talla,
      Color: b.color || "",
      Cantidad: b.cantidad,
      Proveedor: b.proveedor || "",
      "Ref. Polival": b.referencia || "",
      Envío: o.agencia || "",
      Estado: b.estado === "servido" ? "Ya salió" : b.cargaId || o.cargaId ? "En carga" : "Apartado",
    };
  });
  const ws = XLSX.utils.json_to_sheet(filas);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Reservas almacén");
  XLSX.writeFile(wb, "Reservas_almacen_" + dia + ".xlsx");
});
