  if (data.shopify && data.shopify.activo) {
    msg += " · " + data.shopify.enviados + " enviados a Shopify";
    if (data.shopify.errores && data.shopify.errores.length) msg += " · " + data.shopify.errores.length + " con error al enviar a Shopify";
  }
